import java.util.Scanner;
public class JAdjacentDuplicates {
	public static void main(String[] args) {
		//Paso 1: Leer el primer numero que ingresa el usuario
		System.out.println("Ingrese los numeros separados por espacios o nueva linea (ingrese -1 para salir): ");
		Scanner scan = new Scanner(System.in); 
		double num = scan.nextDouble();
		//Paso 2: Leer el resto de los numeros que ingresa el usuario y verificar duplicados adyacentes
		while (num != -1) {
			double previous = num;
			num = scan.nextDouble();
			if (num == previous) {
				System.out.println("Entrada duplicada para el numero: " + num); 
			}
		}
		scan.close();
	}
}

